<script setup>
import { computed, onMounted, reactive, ref } from "vue";
import { Check, ChevronRight, LoaderCircle, MailPlus, Pause, Play, RefreshCw, Send, Trash2, UserPlus, X } from "lucide-vue-next";
import { api } from "../api/client";
const schedules = ref([]); const recipientOptions = ref({ parents: [], external_email_recipients: [] }); const externals = ref([]); const detail = ref(null); const message = ref(""); const error = ref(""); const loading = ref(true); const saving = ref(false); const selectedParents = ref([]); const selectedExternals = ref([]); const form = reactive({ source_type: "custom", title: "", body: "", recurrence: "daily", immediate_send: false, scheduled_at: "", send_time: "08:00", weekday: "1" }); const externalForm = reactive({ name: "", email: "" }); const activeExternals = computed(() => externals.value.filter((item) => item.active)); const statusLabel = { active: "启用", paused: "暂停", completed: "已完成", deleted: "已删除" };
async function load() { loading.value = true; try { const [s, r, e] = await Promise.all([api.get("/admin/parenting_advice_schedules", "admin"), api.get("/admin/parenting_advice/recipient_options", "admin"), api.get("/admin/external_email_recipients", "admin")]); schedules.value = s || []; recipientOptions.value = r || { parents: [], external_email_recipients: [] }; externals.value = e || []; } catch (cause) { error.value = cause.message || "推送数据加载失败"; } finally { loading.value = false; } }
function toggle(list, id) { const value = String(id); return list.includes(value) ? list.filter((item) => item !== value) : [...list, value]; }
async function addExternal() { try { const created = await api.post("/admin/external_email_recipients", externalForm, "admin"); Object.assign(externalForm, { name: "", email: "" }); message.value = "外部邮箱成员已新增"; await load(); if (created?.id) selectedExternals.value.push(String(created.id)); } catch (cause) { error.value = cause.message || "新增失败"; } }
async function deactivate(id) { try { await api.delete(`/admin/external_email_recipients/${id}`, "admin"); message.value = "外部邮箱成员已停用"; await load(); } catch (cause) { error.value = cause.message || "停用失败"; } }
async function createSchedule() { saving.value = true; try { const payload = { source_type: form.source_type, title: form.title || (form.source_type === "whitelist" ? "本期育儿精选" : ""), body: form.source_type === "whitelist" ? "" : form.body, recurrence: form.recurrence, parent_ids: selectedParents.value, external_email_recipient_ids: selectedExternals.value }; if (form.recurrence === "one_time") { payload.immediate_send = form.immediate_send; if (!form.immediate_send) payload.scheduled_at = form.scheduled_at; } else { payload.send_time = form.send_time; } if (form.recurrence === "weekly") payload.weekday = form.weekday; const created = await api.post("/admin/parenting_advice_schedules", payload, "admin"); message.value = form.immediate_send ? "立即发送任务已提交" : "育儿建议推送计划已创建"; detail.value = created; Object.assign(form, { title: "", body: "", recurrence: "daily", immediate_send: false, scheduled_at: "", send_time: "08:00", weekday: "1" }); selectedParents.value = []; selectedExternals.value = []; await load(); } catch (cause) { error.value = cause.message || "计划创建失败"; } finally { saving.value = false; } }
async function action(id, verb) { try { await api.patch(`/admin/parenting_advice_schedules/${id}/${verb}`, {}, "admin"); message.value = verb === "pause" ? "推送计划已暂停" : "推送计划已恢复"; await load(); } catch (cause) { error.value = cause.message || "操作失败"; } }
async function remove(id) { try { await api.delete(`/admin/parenting_advice_schedules/${id}`, "admin"); message.value = "推送计划已删除"; await load(); } catch (cause) { error.value = cause.message || "删除失败"; } }
async function showDetail(id) { try { detail.value = await api.get(`/admin/parenting_advice_schedules/${id}`, "admin"); } catch (cause) { error.value = cause.message || "详情加载失败"; } }
onMounted(load);
</script>
<template><div><div class="page-heading"><div><span class="mono-label">ADMIN / FAMILY INTELLIGENCE</span><h1>育儿建议推送</h1><p>创建单次、每日或每周邮件推送计划。</p></div><button class="button button-dark" @click="load"><RefreshCw :size="15" />刷新</button></div><div v-if="message" class="notice" style="margin-bottom:14px">{{ message }}</div><div v-if="error" class="notice error" style="margin-bottom:14px">{{ error }}</div><section class="surface surface-pad" style="margin-bottom:18px"><div class="surface-title"><h2><Send :size="16" style="vertical-align:-3px; margin-right:6px" />新建推送计划</h2><span>MAIL AUTOMATION</span></div><form class="form-grid" @submit.prevent="createSchedule"><div class="field"><label>内容来源</label><select v-model="form.source_type"><option value="custom">自定义邮件</option><option value="whitelist">白名单自动内容</option></select></div><div class="field"><label>邮件标题</label><input v-model="form.title" required placeholder="本期育儿建议" /></div><div class="field"><label>发送周期</label><select v-model="form.recurrence"><option value="one_time">单次</option><option value="daily">每天</option><option value="weekly">每周</option></select></div><div v-if="form.recurrence === 'one_time'" class="field wide"><label>发送时间</label><div style="display:flex; align-items:center; gap:10px"><input v-model="form.immediate_send" type="checkbox" />立即发送 <input v-if="!form.immediate_send" v-model="form.scheduled_at" type="datetime-local" required /></div></div><div v-else class="field"><label>发送时间</label><input v-model="form.send_time" type="time" required /></div><div v-if="form.recurrence === 'weekly'" class="field"><label>星期</label><select v-model="form.weekday"><option v-for="n in 7" :key="n" :value="String(n)">周{{ ['一','二','三','四','五','六','日'][n-1] }}</option></select></div><div v-if="form.source_type === 'custom'" class="field full"><label>育儿建议正文</label><textarea v-model="form.body" required placeholder="输入本期育儿建议正文" /></div><div v-else class="notice" style="grid-column:1/-1">将从白名单来源自动筛选内容，系统会在发送记录中保留内容来源。</div><div class="field full"><label>选择家长收件人</label><div class="chip-row"><button v-for="parent in recipientOptions.parents" :key="parent.id" type="button" class="chip" :class="{ active: selectedParents.includes(String(parent.id)) }" @click="selectedParents = toggle(selectedParents, parent.id)">{{ parent.name || `家长 #${parent.id}` }} · {{ parent.email }}</button><span v-if="!recipientOptions.parents.length" class="chip">暂无已绑定邮箱的家长</span></div></div><div class="field full"><label>选择外部收件人</label><div class="chip-row"><button v-for="recipient in activeExternals" :key="recipient.id" type="button" class="chip" :class="{ active: selectedExternals.includes(String(recipient.id)) }" @click="selectedExternals = toggle(selectedExternals, recipient.id)">{{ recipient.name }} · {{ recipient.email }}</button><span v-if="!activeExternals.length" class="chip">暂无外部成员</span></div></div><div class="form-actions"><button class="button button-primary" type="submit" :disabled="saving"><LoaderCircle v-if="saving" class="spin" :size="15" />{{ saving ? '创建中...' : form.immediate_send ? '立即发送' : '创建计划' }}</button></div></form></section><div class="data-grid"><section class="surface surface-pad"><div class="surface-title"><h2><UserPlus :size="16" style="vertical-align:-3px; margin-right:6px" />外部邮箱通讯录</h2><span>{{ externals.length }} CONTACTS</span></div><form style="display:flex; gap:8px; flex-wrap:wrap" @submit.prevent="addExternal"><input v-model="externalForm.name" class="filter-input" placeholder="姓名" required /><input v-model="externalForm.email" class="filter-input" type="email" placeholder="邮箱" required /><button class="button button-light" type="submit"><MailPlus :size="14" />新增</button></form><div style="display:grid; gap:7px; margin-top:14px"><div v-for="recipient in externals" :key="recipient.id" style="display:flex; justify-content:space-between; align-items:center; gap:8px; padding:10px; border:1px solid var(--light-line); border-radius:8px; font-size:12px"><span><strong>{{ recipient.name }}</strong><small style="display:block; margin-top:3px; color:#7894a3">{{ recipient.email }}</small></span><button v-if="recipient.active" class="row-action" style="color:#ff9bac" @click="deactivate(recipient.id)"><X :size="13" />停用</button></div></div></section><section class="surface"><div class="surface-title" style="padding:18px 18px 0"><h2>推送计划</h2><span>{{ schedules.length }} SCHEDULES</span></div><div v-if="loading" class="empty-state"><LoaderCircle class="spin" :size="25" /></div><div v-else-if="!schedules.length" class="empty-state">暂无推送计划</div><div v-else class="table-wrap"><table class="data-table"><thead><tr><th>标题</th><th>周期</th><th>下次发送</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="schedule in schedules" :key="schedule.id"><td><strong>{{ schedule.title }}</strong><small style="display:block; margin-top:4px; color:#7894a3">{{ schedule.source_type === 'whitelist' ? '白名单内容' : '自定义邮件' }}</small></td><td>{{ schedule.recurrence === 'one_time' ? '单次' : schedule.recurrence === 'daily' ? `每天 ${schedule.send_time}` : `每周 ${schedule.send_time}` }}</td><td>{{ schedule.next_run_at ? new Date(schedule.next_run_at).toLocaleString('zh-CN') : '-' }}</td><td><span class="status" :class="schedule.status === 'active' ? 'ok' : schedule.status === 'paused' ? 'warn' : 'neutral'">{{ statusLabel[schedule.status] || schedule.status }}</span></td><td><div class="row-actions"><button class="row-action" @click="showDetail(schedule.id)"><ChevronRight :size="13" />详情</button><button v-if="schedule.status === 'active'" class="row-action" @click="action(schedule.id,'pause')"><Pause :size="13" /></button><button v-if="schedule.status === 'paused'" class="row-action" @click="action(schedule.id,'resume')"><Play :size="13" /></button><button class="row-action" style="color:#ff9bac" @click="remove(schedule.id)"><Trash2 :size="13" /></button></div></td></tr></tbody></table></div></section></div><div v-if="detail" class="surface surface-pad" style="margin-top:18px"><div class="surface-title"><h2>推送详情</h2><button class="icon-button" @click="detail=null"><X :size="15" /></button></div><p style="white-space:pre-wrap; color:#65808e; font-size:13px; line-height:1.7">{{ detail.body || '白名单自动内容' }}</p><div v-if="detail.deliveries?.length" style="display:grid; gap:8px; margin-top:14px"><div v-for="delivery in detail.deliveries" :key="delivery.id" class="notice"><Check :size="14" style="vertical-align:-2px; margin-right:5px" />{{ delivery.status }} · 成功 {{ delivery.sent_count }} / 失败 {{ delivery.failed_count }}</div></div></div></div></template>
<style scoped>.spin { animation: spin 1s linear infinite; } @keyframes spin { to { transform:rotate(360deg); } }</style>
